  Precondition._(this._bc, this._bcOffset);
  factory Precondition(List<int> bytes) {
    final rootRef = fb.BufferContext.fromBytes(bytes);
    return reader.read(rootRef, 0);
  }

  static const fb.Reader<Precondition> reader = _PreconditionReader();

  final fb.BufferContext _bc;
  final int _bcOffset;

  bool get wasSnapshotTaken => const fb.BoolReader().vTableGet(_bc, _bcOffset, 4, false);
  SnapshotStats? get snapshotStats => SnapshotStats.reader.vTableGetNullable(_bc, _bcOffset, 6);
  bool get gitHeadImported => const fb.BoolReader().vTableGet(_bc, _bcOffset, 8, false);
  bool get gitHeadReset => const fb.BoolReader().vTableGet(_bc, _bcOffset, 10, false);
  int get gitHeadRebased => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 12, 0);
  int get snapshotRebased => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 14, 0);
  GitImportResult? get gitRefs => GitImportResult.reader.vTableGetNullable(_bc, _bcOffset, 16);
  int get gitRefsRebased => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 18, 0);
  FinishFacts? get finish => FinishFacts.reader.vTableGetNullable(_bc, _bcOffset, 20);
  StaleRecovery? get staleRecovery => StaleRecovery.reader.vTableGetNullable(_bc, _bcOffset, 22);

  @override
  String toString() {
    return 'Precondition{wasSnapshotTaken: ${wasSnapshotTaken}, snapshotStats: ${snapshotStats}, gitHeadImported: ${gitHeadImported}, gitHeadReset: ${gitHeadReset}, gitHeadRebased: ${gitHeadRebased}, snapshotRebased: ${snapshotRebased}, gitRefs: ${gitRefs}, gitRefsRebased: ${gitRefsRebased}, finish: ${finish}, staleRecovery: ${staleRecovery}}';
  }
}

