///  Root FlatBuffers type for every fallible FFI call that returns composite data.
///
///  ok == true  → data is set to the concrete Payload variant; error is absent.
///  ok == false → error is set (code + context); data is absent (Payload::NONE).
///
///  Dart reads the buffer via the generated typed accessors. It is released by
///  reclaiming the exact Rust allocation through one of two equivalent paths:
///  zanshin_buffer_free(ptr, len) for synchronous call sites, or the
///  NativeFinalizer-backed token path (zanshin_buffer_free_token) used by the
///  FfiBuffer wrapper as a belt-and-suspenders backstop
///  (see app/lib/src/ffi/ffi_buffer.dart).
///
///  `precondition` (Story 9.26) is PRESENT whenever the verb's pre-verb snapshot RAN — on the ok
///  envelope and on an error envelope alike (then PARTIAL). It is ABSENT when the call was refused
///  before the verb ran (a null pointer, an invalid handle, a request buffer that fails
///  validation) and on every symbol that runs no pre-verb snapshot (open/init/clone/detect/close,
///  `zanshin_workspace_root`, `zanshin_log_defaults`, `zanshin_commit_contents`, events, and every
///  `zanshin_config_*` symbol except `zanshin_config_set`). `zanshin_config_set` carries it iff its `user.name`/`user.email`
///  working-copy check ran the snapshot (Story 9.28). `zanshin_repo_convert` carries the
///  conversion's snapshot report (`jj git init`'s `maybe_snapshot`, Story 9.33) iff that snapshot
///  started — on its ok envelope and on its error envelope (the state it describes stays on disk:
///  a conversion is never rolled back, Story 9.57). `zanshin_snapshot`'s success is `ok` with NO `data` and the precondition set.
///  `zanshin_workspace_update_stale` runs no pre-verb snapshot — it IS the recovery — and carries
///  the recovery's TRAILING snapshot report (Story 9.23), on its ok and its error envelope.
///
///  `warnings` (Story 9.32) are the call's warnings in the jj CLI's print order, on the ok
///  envelope AND on an error envelope (then everything warned before the failure). ABSENT when
///  the call had nothing to warn about — every reader treats absent as an empty list — and
///  therefore on every symbol that cannot warn, and on the pre-serialised `internal.panic`
///  fallback. Success without caveat is `ok` with no warnings; there is no severity field.
class Envelope {
  Envelope._(this._bc, this._bcOffset);
  factory Envelope(List<int> bytes) {
    final rootRef = fb.BufferContext.fromBytes(bytes);
    return reader.read(rootRef, 0);
  }

  static const fb.Reader<Envelope> reader = _EnvelopeReader();

  final fb.BufferContext _bc;
  final int _bcOffset;

  bool get ok => const fb.BoolReader().vTableGet(_bc, _bcOffset, 4, false);
  FfiError? get error => FfiError.reader.vTableGetNullable(_bc, _bcOffset, 6);
  PayloadTypeId? get dataType =>
      PayloadTypeId._createOrNull(const fb.Uint8Reader().vTableGetNullable(_bc, _bcOffset, 8));
  dynamic get data {
    switch (dataType?.value) {
      case 1:
        return RepoHandle.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 2:
        return Diagnostics.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 3:
        return Status.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 4:
        return Change.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 5:
        return OpLog.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 6:
        return Bookmarks.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 7:
        return Remotes.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 8:
        return RepoDetect.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 9:
        return WatcherEvent.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 10:
        return Progress.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 11:
        return GraphTopology.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 12:
        return LogDefaults.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 13:
        return MutationResult.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 14:
        return AbsorbResult.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 15:
        return FileList.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 16:
        return FileContents.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 17:
        return FileAnnotation.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 18:
        return FileSearch.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 19:
        return GitImportResult.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 20:
        return GitExportResult.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 21:
        return ShowView.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 22:
        return EvologView.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 23:
        return InterdiffView.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 24:
        return WorkspaceList.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 25:
        return WorkspaceRoot.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 26:
        return TrackResult.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 27:
        return UntrackResult.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 28:
        return ConfigListResult.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 29:
        return ConfigGetResult.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 30:
        return ConfigPathResult.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 31:
        return ConfigSetResult.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 32:
        return ConfigUnsetResult.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 33:
        return ConfigFileText.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 34:
        return ConfigGcList.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 35:
        return ConfigGcResult.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 36:
        return CommitContents.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 37:
        return WorkspaceAddResult.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 38:
        return StaleRecovery.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 39:
        return SquashPlan.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 40:
        return SplitResult.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 41:
        return GitPushResult.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 42:
        return GitPushRemotes.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 43:
        return RemoteChanges.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 44:
        return GitFetchResult.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 45:
        return GitFetchRemotes.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 46:
        return DropActions.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 47:
        return ChangeActions.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 48:
        return FixResult.reader.vTableGetNullable(_bc, _bcOffset, 10);
      default:
        return null;
    }
  }

  Precondition? get precondition => Precondition.reader.vTableGetNullable(_bc, _bcOffset, 12);
  List<Warning>? get warnings => const fb.ListReader<Warning>(Warning.reader).vTableGetNullable(_bc, _bcOffset, 14);

  @override
  String toString() {
    return 'Envelope{ok: ${ok}, error: ${error}, dataType: ${dataType}, data: ${data}, precondition: ${precondition}, warnings: ${warnings}}';
  }
}

class _EnvelopeReader extends fb.TableReader<Envelope> {
  const _EnvelopeReader();

  @override
  Envelope createObject(fb.BufferContext bc, int offset) => Envelope._(bc, offset);
}

class EnvelopeBuilder {
  EnvelopeBuilder(this.fbBuilder);

  final fb.Builder fbBuilder;

  void begin() {
    fbBuilder.startTable(6);
  }

  int addOk(bool? ok) {
    fbBuilder.addBool(0, ok);
    return fbBuilder.offset;
  }

  int addErrorOffset(int? offset) {
    fbBuilder.addOffset(1, offset);
    return fbBuilder.offset;
  }

  int addDataType(PayloadTypeId? dataType) {
    fbBuilder.addUint8(2, dataType?.value);
    return fbBuilder.offset;
  }

  int addDataOffset(int? offset) {
    fbBuilder.addOffset(3, offset);
    return fbBuilder.offset;
  }

  int addPreconditionOffset(int? offset) {
    fbBuilder.addOffset(4, offset);
    return fbBuilder.offset;
  }

  int addWarningsOffset(int? offset) {
    fbBuilder.addOffset(5, offset);
    return fbBuilder.offset;
  }

  int finish() {
    return fbBuilder.endTable();
  }
}

class EnvelopeObjectBuilder extends fb.ObjectBuilder {
  final bool? _ok;
  final FfiErrorObjectBuilder? _error;
  final PayloadTypeId? _dataType;
  final dynamic _data;
  final PreconditionObjectBuilder? _precondition;
  final List<WarningObjectBuilder>? _warnings;

  EnvelopeObjectBuilder({
    bool? ok,
    FfiErrorObjectBuilder? error,
    PayloadTypeId? dataType,
    dynamic data,
    PreconditionObjectBuilder? precondition,
    List<WarningObjectBuilder>? warnings,
  }) : _ok = ok,
       _error = error,
       _dataType = dataType,
       _data = data,
       _precondition = precondition,
       _warnings = warnings;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? errorOffset = _error?.getOrCreateOffset(fbBuilder);
    final int? dataOffset = _data?.getOrCreateOffset(fbBuilder);
    final int? preconditionOffset = _precondition?.getOrCreateOffset(fbBuilder);
    final int? warningsOffset = _warnings == null
        ? null
        : fbBuilder.writeList(_warnings!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    fbBuilder.startTable(6);
    fbBuilder.addBool(0, _ok);
    fbBuilder.addOffset(1, errorOffset);
    fbBuilder.addUint8(2, _dataType?.value);
    fbBuilder.addOffset(3, dataOffset);
    fbBuilder.addOffset(4, preconditionOffset);
    fbBuilder.addOffset(5, warningsOffset);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
}
